  "labels": [
    {
      "label": "S_Competition",
      "span": "all you play against after 8k trophies is mega knight,pekka, and golem",
      "rationale": "This explicitly describes the player competing against other players."
    },
    {
      "label": "M_PayToProgress",
      "span": "its also pay to win",
      "rationale": "This explicitly describes spending money to gain an advantage in gameplay."
    }
  ],
  "invoked_web_search": false,
